\n                cell = cell.strip()\n                # Clean up - remove footnotes\n                cell = re.sub(r'\\d+/', '', cell)  # remove footnote markers like 7/\n                cell = cell.rstrip('r')  # remove revision marker\n                if cell and cell not in ['*', '']:\n                    first_table_data.append(cell)\n\n# Second table\nsecond_table_data = []\nfor i in range(27, 50):  # rows 27-49 \n    if i < len(rows):\n        cells = re.findall(r'<t[dh]>([^<]*)</t[dh]>', rows[i])\n        # First column is the row header (year/month), skip it\n        # Cells: [year, Dollars, Fractional coin, Total, Total Currency, Per capita]\n        if len(cells) > 1:\n            for cell in cells[1:]:\n                cell = cell.strip()\n                cell = re.sub(r'\\d+/', '', cell)  # remove footnote markers\n                cell = cell.rstrip('r')  # remove revision marker\n                if cell and cell not in ['*', '']:\n                    second_table_data.append(cell)\n\n# Combine all data points\nall_data = first_table_data + second_table_data\n\nprint(\"First table data values:\")\nfor i, v in enumerate(first_table_data):\n    print(f\"  {i}: {v}\")\n\nprint(f\"\\nSecond table data values:\")\nfor i, v in enumerate(second_table_data):\n    print(f\"  {i}: {v}\")\n\nprint(f\"\\nTotal data points: {len(all_data)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
